// Formatting and small maths shared by the panel: no engine calls and no words here.
import type { Category, Item, LimitTrack, Point } from '../types'

const BARS = '▁▂▃▄▅▆▇█'
const EIGHTHS = ' ▁▂▃▄▅▆▇█'
// A flat guess per image: the transcript does not carry their pixel size.
export const IMAGE_TOKENS = 1500

type Block = { type: string; [field: string]: unknown }
export type Message = { role: 'user' | 'assistant'; content: readonly Block[] }

export function k(tokens: number): string {
  if (tokens >= 1_000_000) return `${(tokens / 1_000_000).toFixed(1).replace(/\.0$/, '')}M`
  if (tokens >= 9_950) return `${Math.round(tokens / 1000)}k`
  if (tokens >= 1000) return `${(tokens / 1000).toFixed(1).replace(/\.0$/, '')}k`
  return String(tokens)
}

// Cut a text to max characters on a word boundary, ending with an ellipsis.
export function shorten(text: string, max: number): string {
  if (text.length <= max) return text
  const cut = text.slice(0, max - 1)
  const space = cut.lastIndexOf(' ')
  return `${(space > max / 2 ? cut.slice(0, space) : cut).trimEnd()}…`
}

// The whole call, for a jump opened in the panel: description, full command or path, capped.
export function detail(e: Record<string, unknown>): string {
  const tool = String(e.tool)
  const short = tool.startsWith('mcp__') ? tool.split('__').slice(1).join(':') : tool
  const str = (v: unknown) => (typeof v === 'string' ? v : '')
  const main = str(e.file_path) || str(e.skill) || str(e.command) || str(e.query) || str(e.url) || str(e.pattern)
  const desc = str(e.description)
  const arg = desc && main && desc !== main ? `${desc}: ${main}` : desc || main
  return shorten(arg ? `${short} ${arg}` : short, 400)
}

// Text broken into lines of at most `width`: on spaces, and a word longer than a line is split.
export function wrapLines(text: string, width: number): string[] {
  const out: string[] = []
  let line = ''
  for (const word of text.split(/\s+/).filter(Boolean)) {
    let w = word
    while (w.length > width) {
      if (line) out.push(line)
      line = ''
      out.push(w.slice(0, width))
      w = w.slice(width)
    }
    if (!line) line = w
    else if (line.length + 1 + w.length <= width) line += ` ${w}`
    else {
      out.push(line)
      line = w
    }
  }
  if (line) out.push(line)
  return out
}

// Parts joined with " · " and wrapped to `width`; the dot stays with the part before it, so a
// line never starts with it. Empty parts are left out.
export function joinLines(parts: readonly string[], width: number): string[] {
  // A character no text holds keeps each dot glued to the word before it while wrapping.
  const GLUE = '\u0001'
  return wrapLines(parts.filter(Boolean).join(`${GLUE}· `), width).map(l => l.split(GLUE).join(' '))
}

// A name cut to its column with an ellipsis; a short one is left as it is.
export function clip(text: string, width: number): string {
  return text.length > width ? `${text.slice(0, Math.max(0, width - 1))}…` : text
}

// A text in exactly `width` cells: padded, or cut with an ellipsis so it never runs into the next.
export function fitCell(text: string, width: number): string {
  return text.length > width ? `${text.slice(0, Math.max(0, width - 1))}…` : text.padEnd(width)
}

// Action prices: one column when the pane is narrow, two when wide, each at most 36 cells so a
// number stays next to its name.
export function priceGrid(width: number): { columns: 1 | 2; width: number } {
  return width < 60 ? { columns: 1, width: Math.min(width, 40) } : { columns: 2, width: Math.min(36, Math.floor((width - 4) / 2)) }
}

// Name column for group and entry lists: what is left after tokens, share, the chevron and,
// on a group page, `bar` cells for the bar.
export function nameWidth(width: number, bar = 0): number {
  return Math.min(30, Math.max(12, width - 17 - bar))
}

// Group name for a tool: built-in tools by name, MCP tools by server.
export function kind(tool: string): string {
  return tool.startsWith('mcp__') ? `MCP ${server(tool.split('__')[1] ?? '')}` : tool
}

// An MCP server's name for a label: a UUID in it shows as its first 8 characters, which tell
// servers apart; the whole text (detail) keeps it in full.
const UUID = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi
export function server(name: string): string {
  return name.replace(UUID, id => id.slice(0, 8))
}

// Short name for a tool call: tool plus its main argument.
export function label(e: Record<string, unknown>): string {
  const tool = String(e.tool)
  const short = tool.startsWith('mcp__') ? server(tool.split('__').slice(1).join(':')) : tool
  const arg =
    (typeof e.file_path === 'string' && e.file_path.split('/').pop()) ||
    (typeof e.skill === 'string' && e.skill) ||
    (typeof e.description === 'string' && e.description) ||
    (typeof e.command === 'string' && e.command.split(/\s+/).slice(0, 2).join(' ')) ||
    (typeof e.query === 'string' && e.query) ||
    (typeof e.url === 'string' && e.url) ||
    (typeof e.pattern === 'string' && e.pattern) ||
    ''
  return arg ? `${short} ${shorten(arg, 45)}` : short
}

// A column chart from zero, one column per value, top row first; each cell in eighths.
export function chartRows(values: readonly number[], height: number): string[] {
  const max = Math.max(0, ...values)
  return Array.from({ length: height }, (_, i) => {
    const row = height - 1 - i
    return values
      .map(v => {
        const level = max > 0 ? Math.round((v / max) * height * 8) : 0
        return EIGHTHS[Math.min(8, Math.max(0, level - row * 8))]
      })
      .join('')
  })
}

// The empty part of a meter: a translucent grey reads on light and dark backgrounds alike.
const TRACK = 'fill="#808080" fill-opacity="0.25"'
const num = (x: number) => String(Math.round(x * 100) / 100)

// The desktop's graphics. Its layout is not a cell grid, so the markup is wide and stretched
// (preserveAspectRatio none) and the element is drawn with no width: it fills its slot, and the
// caller sets the height in pixels. Square ends: rounded corners would stretch with the strip.
const WIDE = 1000

// A strip filled to `fraction` (0 to 1) in `color`; with `track`, the rest faint. A share above zero
// shows at least a sliver. `opacity` below 1 lets a lit background show through the fill.
export function lineSvg(fraction: number, color: string, opts: { track?: boolean; opacity?: number } = {}): string {
  const h = 10
  const f = Math.min(1, Math.max(0, fraction))
  const filled = f > 0 ? Math.min(WIDE, Math.max(WIDE / 200, f * WIDE)) : 0
  const alpha = opts.opacity !== undefined && opts.opacity < 1 ? ` fill-opacity="${opts.opacity}"` : ''
  const bg = opts.track ? `<rect x="0" y="0" width="${WIDE}" height="${h}" ${TRACK}/>` : ''
  const fg = filled > 0 ? `<rect x="0" y="0" width="${num(filled)}" height="${h}" fill="${color}"${alpha}/>` : ''
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDE}" height="${h}" viewBox="0 0 ${WIDE} ${h}" preserveAspectRatio="none">${bg}${fg}</svg>`
}

// A title set in capitals for the terminal, as a sentence: "5-HOUR LIMIT" → "5-hour limit".
export function sentenceCase(text: string): string {
  return text === text.toUpperCase() ? text.charAt(0) + text.slice(1).toLowerCase() : text
}

const two = (n: number) => String(n).padStart(2, '0')

// Local time: HH:MM today, otherwise DD.MM HH:MM.
export function resetLabel(iso: string, now: number): string {
  const at = new Date(iso)
  const today = new Date(now)
  const time = `${two(at.getHours())}:${two(at.getMinutes())}`
  const isToday =
    at.getFullYear() === today.getFullYear() && at.getMonth() === today.getMonth() && at.getDate() === today.getDate()
  return isToday ? time : `${two(at.getDate())}.${two(at.getMonth() + 1)} ${time}`
}

// Average rise per turn: over the last five turns and over all of them.
export function pace(points: readonly Point[]): { recent: number; overall: number } {
  const rises: number[] = []
  for (let i = 1; i < points.length; i++) rises.push(Math.max(0, points[i]!.tokens - points[i - 1]!.tokens))
  const mean = (xs: number[]) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0)
  return { recent: mean(rises.slice(-5)), overall: mean(rises) }
}

// How much the context grew each turn; drops (compactions) are left out.
function rises(points: readonly { tokens: number }[]): number[] {
  const out: number[] = []
  for (let i = 1; i < points.length; i++) {
    const d = points[i]!.tokens - points[i - 1]!.tokens
    if (d > 0) out.push(d)
  }
  return out
}

function median(xs: readonly number[]): number {
  const s = [...xs].sort((a, b) => a - b)
  const mid = Math.floor(s.length / 2)
  return s.length % 2 ? s[mid]! : (s[mid - 1]! + s[mid]!) / 2
}

// The usual rise per turn: the median, over past sessions, of each one's median rise.
// Medians, so one session full of screenshots doesn't set the norm.
export function usualRise(logs: readonly { points: readonly { tokens: number }[] }[]): number | null {
  const perSession = logs.map(l => rises(l.points)).filter(r => r.length >= 5).map(median)
  return perSession.length >= 3 ? median(perSession) : null
}

export type SpeedKind = 'snail' | 'cat' | 'rabbit' | 'rocket'

// The last few turns against the usual pace.
export function speed(points: readonly Point[], usual: number | null): { kind: SpeedKind; ratio: number } | null {
  const recent = rises(points).slice(-5)
  if (!usual || recent.length < 3) return null
  const ratio = Math.round((median(recent) / usual) * 100) / 100
  const kind: SpeedKind = ratio < 0.67 ? 'snail' : ratio < 1.5 ? 'cat' : ratio < 2 ? 'rabbit' : 'rocket'
  return { kind, ratio }
}

const LIMIT_SAMPLES = 300
const MINUTE = 60_000

// Samples of one limit window; a new reset time starts a new track.
export function trackLimit(track: LimitTrack | null, resetsAt: string, at: number, percent: number): LimitTrack {
  const samples = track?.resetsAt === resetsAt ? track.samples : []
  return { resetsAt, samples: [...samples, { at, percent }].slice(-LIMIT_SAMPLES) }
}

// When the limit runs out at the pace of the last hour; 'untilReset' when it lasts until the reset.
// Null until there are at least ten minutes of samples in that hour.
export function limitForecast(track: LimitTrack, now: number, resetsAt: number): { minutes: number } | 'untilReset' | null {
  const recent = track.samples.filter(s => s.at >= now - 60 * MINUTE)
  const first = recent[0]
  const last = recent[recent.length - 1]
  if (!first || !last || now - first.at < 10 * MINUTE) return null
  const perMinute = (last.percent - first.percent) / ((now - first.at) / MINUTE)
  if (perMinute <= 0) return 'untilReset'
  const minutes = Math.round((100 - last.percent) / perMinute)
  return now + minutes * MINUTE >= resetsAt ? 'untilReset' : { minutes }
}

// What each turn added to the context, oldest first; a compaction's drop counts as nothing.
export function turnRises(points: readonly { tokens: number }[]): number[] {
  return points.slice(1).map((p, i) => Math.max(0, p.tokens - points[i]!.tokens))
}

// The biggest rises from one turn to the next, with what likely caused them.
type Jump = { delta: number; turn: number; cause: string | null; detail: string | null }

export function jumps(points: readonly Point[], n: number): Jump[] {
  const out: Jump[] = []
  for (let i = 1; i < points.length; i++) {
    const delta = points[i]!.tokens - points[i - 1]!.tokens
    if (delta > 0) out.push({ delta, turn: points[i]!.turn, cause: points[i]!.cause, detail: points[i]!.detail ?? null })
  }
  return out.sort((a, b) => b.delta - a.delta).slice(0, n)
}

// The /context rows that sit in the window: used content by size, then free space.
export function windowRows(
  rows: readonly { name: string; tokens: number; kind: string; color: string }[],
): Category[] {
  const used = rows.filter(r => r.kind === 'used').sort((a, b) => b.tokens - a.tokens)
  const free = rows.filter(r => r.kind === 'free')
  return [...used, ...free].map(({ name, tokens, color, kind }) => ({ name, tokens, color, isFree: kind === 'free' }))
}

type BreakdownLists = {
  categories: readonly { name: string; tokens: number }[]
  skills?: { skillFrontmatter: readonly { name: string; tokens: number }[] }
  memoryFiles: readonly { path: string; tokens: number }[]
  mcpTools: readonly { name: string; serverName: string; tokens: number; isLoaded: boolean }[]
  agents: readonly { agentType: string; tokens: number }[]
}

// Per-item lists for the /context categories that have them, keyed by the category's name.
export function detailsFor(b: BreakdownLists): Record<string, Item[]> {
  const lists: [RegExp, () => Item[]][] = [
    [/skill/i, () => (b.skills?.skillFrontmatter ?? []).map(s => ({ name: s.name, tokens: s.tokens }))],
    [/memory/i, () => b.memoryFiles.map(f => ({ name: f.path.split('/').slice(-2).join('/'), tokens: f.tokens }))],
    [/mcp tools/i, () => b.mcpTools.filter(t => t.isLoaded).map(t => ({ name: `${server(t.serverName)}: ${t.name}`, tokens: t.tokens }))],
    [/agent/i, () => b.agents.map(a => ({ name: a.agentType, tokens: a.tokens }))],
  ]
  const out: Record<string, Item[]> = {}
  for (const { name } of b.categories) {
    const match = lists.find(([re]) => re.test(name))
    const items = match ? match[1]() : []
    if (items.length > 0) out[name] = [...items].sort((x, y) => y.tokens - x.tokens)
  }
  return out
}

